// AWI: ganti nama BYD Ti7 -> BYD TiTAN 7 DM (sekali jalan, hapus setelah dipakai)
function awi_ti7_rename($s) {
	return preg_replace_callback('/(?<![A-Za-z0-9\/_.-])(BYD )?Ti7(?![A-Za-z0-9])( (?:FWD|AWD))?/', function ($m) {
		$byd = isset($m[1]) ? $m[1] : '';
		$drv = isset($m[2]) ? $m[2] : '';
		return $drv !== '' ? $byd . 'TiTAN 7' . $drv : $byd . 'TiTAN 7 DM';
	}, (string) $s);
}
add_action('rest_api_init', function () {
	register_rest_route('awi/v1', '/ti7fix', array(
		'methods' => 'POST',
		'permission_callback' => function () { return current_user_can('manage_options'); },
		'callback' => function () {
			global $wpdb;
			$out = array();
			foreach (array(10496, 10706, 10707, 10818) as $id) {
				$p = $wpdb->get_row($wpdb->prepare("SELECT post_title, post_excerpt, post_content FROM {$wpdb->posts} WHERE ID=%d", $id));
				if (!$p) { $out['p' . $id] = 'missing'; continue; }
				$new = array(
					'post_title' => awi_ti7_rename($p->post_title),
					'post_excerpt' => awi_ti7_rename($p->post_excerpt),
					'post_content' => awi_ti7_rename($p->post_content),
				);
				if ($id === 10706) $new['post_title'] = 'BYD TiTAN 7 DM';
				$ch = array();
				foreach ($new as $k => $v) if ($v !== $p->$k) $ch[$k] = substr_count($p->$k, 'Ti7') . '>' . substr_count($v, 'Ti7');
				if ($ch) { $wpdb->update($wpdb->posts, $new, array('ID' => $id)); clean_post_cache($id); }
				$out['p' . $id] = array('changes' => $ch, 'title' => $new['post_title']);
			}
			$metas = $wpdb->get_results("SELECT meta_id, post_id, meta_key, meta_value FROM {$wpdb->postmeta} WHERE meta_value LIKE BINARY '%Ti7%' AND meta_key IN ('_wp_attachment_image_alt','_yoast_wpseo_title','_yoast_wpseo_metadesc','_yoast_wpseo_opengraph-title','_yoast_wpseo_opengraph-description','_yoast_wpseo_twitter-title','_yoast_wpseo_twitter-description')");
			foreach ($metas as $r) {
				$v = awi_ti7_rename($r->meta_value);
				if ($v !== $r->meta_value) { update_post_meta($r->post_id, $r->meta_key, $v, $r->meta_value); $out['meta'][] = $r->post_id . ' ' . $r->meta_key . ': ' . mb_substr($v, 0, 70); }
			}
			$t = $wpdb->prefix . 'snippets';
			foreach (array(9, 14, 29) as $sid) {
				$c = $wpdb->get_var($wpdb->prepare("SELECT code FROM $t WHERE id=%d", $sid));
				$n = awi_ti7_rename($c);
				if ($n !== $c) { $wpdb->update($t, array('code' => $n), array('id' => $sid)); }
				$out['s' . $sid] = substr_count($c, 'Ti7') . '>' . substr_count($n, 'Ti7');
			}
			$bs = chr(92);
			if (function_exists('Code_Snippets' . $bs . 'clean_snippets_cache')) { call_user_func('Code_Snippets' . $bs . 'clean_snippets_cache', $t); $out['cache'] = 'cs'; }
			wp_cache_flush();
			return $out;
		},
	));
});
